node --no-warnings --input-type=module <<'NODE'
import { registerHooks } from 'node:module';
import { existsSync } from 'node:fs';
import { loadVendorFile } from './tools/node-vendor.mjs';
registerHooks({resolve(specifier, context, next) {
  if (context.parentURL?.endsWith('.ts') && specifier.startsWith('.') && specifier.endsWith('.js')) {
    const url = new URL(specifier.slice(0,-3) + '.ts', context.parentURL);
    if (existsSync(url)) return next(url.href, context);
  }
  return next(specifier, context);
}});
for (const path of ['compiler/typed/tape.js','compiler/typed/typed-wasm.js','bench/host/rv32-interp.js','compiler/typed/typed-rv32.js','compiler/typed/typed-rv32-inline.js','compiler/typed/typed-rv32-loops.js','compiler/typed/typed-rv32-kernel.js']) loadVendorFile(path);
const { setVendor } = await import('./src/typed/vendor.ts');
setVendor({typedTape, typedWasm, typedRv32, typedRv32Interp});
const { Program } = await import('./src/typed/program.ts');
const B = await import('./src/typed/backend/index.ts');
const source = `function inRange(c: i32, lo: i32, hi: i32): bool { return c >= lo && c <= hi; }
function probe(pattern: buffer, text: buffer): i32 {
    const stack = new Int32Array(20);
    let i = pattern.length - 1;
    let n = 0;
    while (i >= 0) {
        const c = pattern.charCodeAt(i);
        stack[i] = c;
        i = i - 1;
        if (!inRange(c, 97, 122)) { continue; }
        n = n + 1;
    }
    if (text.length > 0 && stack[0] == text.charCodeAt(0)) { return n; }
    return 0;
}`;
const inputs = {probe:{pattern:{string:'ab'},text:{buffer:[0,12],cell:[97,100]}}, inRange:{c:[0,127],lo:[97,122],hi:[97,122]}};
const p = new Program('probe', source, {inputs});
if (p.status !== 'ok') throw Error(JSON.stringify(p.error));
const args=['ab', 'a'];
const r0=p.exec('probe',args);
const settings=await p.pipeline('speed');
const opt=p.exec('probe',args);
const img=B.lowerToImage(p.head).image;
const rv=p.exec('probe',args,{engine:'rv32',image:img});
const ref=typedRv32.compile(source,[],undefined);
const refImg=B.imageFromCode('probe',ref.image,ref.entries);
const refCheck=p.check({count:10,against:(fn,k)=>B.runImage(refImg,fn,k.args,k.memory,{limit:2e5})});
const regs = [...['','aab','aac','acb','aac
'].map(t => +new RegExp('^(?:[a-b]*c?)(?![\s\S])').test(t))];
if ([r0,opt,rv].some(r=>r.result!==2||r.trap||r.limit)||refCheck.status!=='agree'||regs.join()!=='1,1,1,0,0') throw Error(JSON.stringify({r0,opt,rv,refCheck,regs}));
console.log(JSON.stringify({steps:[r0.steps,opt.steps,rv.steps],cases:p.cases('probe',{count:1}).length,changed:settings.steps.filter(s=>s.changed).length, reference:refCheck.status,regs}));
NODE

